import React, { useState, useMemo } from "react";

// PenRunner — Home portale v4 (registro scuro, produttizzata)
// L'ultima iterazione scura + le maniglie da prodotto dell'originale:
// navigazione, ricerca funzionante, filtri regione, footer.
// Foto segnaposto: LICENZE DA REGOLARIZZARE — non per produzione.

const F_LIVE = "data:image/jpeg;base64,";
const F_PREMI = "data:image/jpeg;base64,";
const F_SABBIA = "data:image/jpeg;base64,";
const F_COPERTO = "data:image/jpeg;base64,";
const F_HERO2 = "data:image/jpeg;base64,";
const F_SPIN = "data:image/jpeg;base64,";
const F_ARENA = "data:image/jpeg;base64,";
const F_STOP = "data:image/jpeg;base64,";
const LOGO_LR = "data:image/png;base64,";

const C = {
  accent: "#15803D", accent500: "#16A34A",
  ink900: "#0B1120", panel: "#141C2E", panel2: "#1E293B",
  slate300: "#CBD5E1", slate400: "#94A3B8", slate500: "#64748B",
  white: "#FFFFFF", live: "#DC2626", gold: "#C8902F", warn: "#F59E0B",
};
const num = { fontVariantNumeric: "tabular-nums" };

const EVENTI = [
  { id: "live", nome: "Cremona Reining Classic", date: "oggi · terzo giorno", luogo: "Cremona", regione: "Lombardia", cover: F_LIVE, tipo: "photo",
    stato: "live", statoTxt: "Green · L1 in corsa · run 3 di 6", cta: "Segui la diretta" },
  { id: "lr5", nome: "Lombardia Reining · 5ª tappa", date: "25–30 agosto", luogo: "Cremona Fiere", regione: "Lombardia", cover: LOGO_LR, tipo: "logo",
    stato: "annunciato", statoTxt: "Box e preiscrizioni dal 5 agosto", extra: "Added 20.650 €" },
  { id: "derby", nome: "Estate Derby", date: "26–27 settembre", luogo: "Manerbio", regione: "Lombardia", cover: F_PREMI, tipo: "photo",
    stato: "annunciato", statoTxt: "Iscrizioni dal 1 agosto", extra: "Open · Non Pro · Youth" },
  { id: "autumn", nome: "Autumn Slide", date: "10–11 ottobre", luogo: "Travagliato", regione: "Lombardia", cover: F_COPERTO, tipo: "photo",
    stato: "annunciato", statoTxt: "Iscrizioni dal 20 agosto", extra: "6 classi" },
  { id: "trofeo", nome: "Trofeo delle Regioni", date: "17–19 ottobre", luogo: "Verona", regione: "Veneto", cover: F_ARENA, tipo: "photo",
    stato: "annunciato", statoTxt: "Iscrizioni dal 1 settembre", extra: "Added 4.000 €" },
  { id: "winter", nome: "Winter Slide Indoor", date: "21–22 novembre", luogo: "Cremona", regione: "Lombardia", cover: F_SPIN, tipo: "photo",
    stato: "annunciato", statoTxt: "Iscrizioni dal 15 settembre", extra: "5 classi" },
  { id: "snaffle", nome: "Snaffle Bit Classic", date: "28–29 novembre", luogo: "Brescia", regione: "Lombardia", cover: F_STOP, tipo: "photo",
    stato: "annunciato", statoTxt: "Iscrizioni dal 1 ottobre", extra: "Open · Non Pro" },
  { id: "lr4", nome: "Lombardia Reining · 4ª tappa", date: "11–13 luglio", luogo: "Cremona Fiere", regione: "Lombardia", cover: LOGO_LR, tipo: "logo",
    stato: "concluso", statoTxt: "Open: Gunners Dream · Ferrari S. · 221,5" },
  { id: "estate", nome: "Estate Reining Show", date: "20–22 giugno", luogo: "Manerbio", regione: "Lombardia", cover: F_HERO2, tipo: "photo",
    stato: "concluso", statoTxt: "Open L4: Gunners Dream · Ferrari S." },
  { id: "lr3c", nome: "Lombardia Reining · 3ª tappa", date: "6–8 giugno", luogo: "Cremona Fiere", regione: "Lombardia", cover: LOGO_LR, tipo: "logo",
    stato: "concluso", statoTxt: "Open: Whizard Jac · Bianchi L. · 219,0" },
  { id: "spring", nome: "Spring Festival", date: "9–10 maggio", luogo: "Cremona", regione: "Lombardia", cover: F_SABBIA, tipo: "photo",
    stato: "concluso", statoTxt: "Rookie 1: Shiny Little Step · Rossi M." },
  { id: "lr2", nome: "Lombardia Reining · 2ª tappa", date: "25–27 aprile", luogo: "Cremona Fiere", regione: "Lombardia", cover: LOGO_LR, tipo: "logo",
    stato: "concluso", statoTxt: "Rookie 1: Shiny Little Step · Rossi M." },
  { id: "lr1", nome: "Lombardia Reining · 1ª tappa", date: "21–23 marzo", luogo: "Cremona Fiere", regione: "Lombardia", cover: LOGO_LR, tipo: "logo",
    stato: "concluso", statoTxt: "Non Pro: Chocowhiz · De Rossi M." },
];

const REGIONI = ["Tutte", "Lombardia", "Piemonte", "Emilia-Romagna", "Veneto"];

const BADGE = {
  live: { txt: "● IN DIRETTA", bg: "#7F1D1D", col: "#FCA5A5" },
  iscrizioni: { txt: "Iscrizioni aperte", bg: "#14532D", col: "#DCFCE7" },
  annunciato: { txt: "Annunciato", bg: "#1E3A5F", col: "#BFDBFE" },
  concluso: { txt: "Concluso", bg: "#334155", col: "#CBD5E1" },
};

const NavLink = ({ children }) => (
  <span style={{ fontSize: 13.5, fontWeight: 500, color: C.slate300, cursor: "pointer" }}>{children}</span>
);

const Lente = () => (
  <svg viewBox="0 0 24 24" style={{ position: "absolute", left: 13, top: "50%", transform: "translateY(-50%)", width: 15, height: 15 }} fill="none" stroke={C.slate500} strokeWidth="2.4" strokeLinecap="round">
    <circle cx="11" cy="11" r="7" /><path d="M20 20l-4.2-4.2" />
  </svg>
);

function Cover({ ev }) {
  if (ev.tipo === "logo") return (
    <div style={{ position: "absolute", inset: 0, background: "#FFFFFF", display: "flex", alignItems: "center", justifyContent: "center" }}>
      <img src={ev.cover} alt="" style={{ maxWidth: "54%", maxHeight: "54%" }} />
    </div>
  );
  return <img src={ev.cover} alt="" style={{ position: "absolute", inset: 0, width: "100%", height: "100%", objectFit: "cover" }} />;
}

function CardEvento({ ev }) {
  const b = BADGE[ev.stato];
  return (
    <div style={{ borderRadius: 12, overflow: "hidden", background: C.panel, cursor: "pointer", boxShadow: "0 6px 22px rgba(0,0,0,.35)" }}>
      <div style={{ position: "relative", aspectRatio: "16/9" }}>
        <Cover ev={ev} />
        <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to top, rgba(11,17,32,.94) 0%, rgba(11,17,32,.28) 55%, rgba(11,17,32,0) 100%)" }} />
        <span style={{ position: "absolute", top: 10, left: 10, background: b.bg, color: b.col, borderRadius: 6, padding: "3px 9px", fontSize: 10.5, fontWeight: 800, letterSpacing: 0.4 }}>{b.txt}</span>
        <div style={{ position: "absolute", left: 12, right: 12, bottom: 10, color: C.white }}>
          <div style={{ fontSize: 10.5, color: C.slate300, textTransform: "uppercase", letterSpacing: 1, ...num }}>{ev.date} · {ev.luogo}</div>
          <div style={{ fontSize: 16.5, fontWeight: 800, letterSpacing: -0.2 }}>{ev.nome}</div>
        </div>
      </div>
      <div style={{ padding: "9px 12px 12px", display: "flex", alignItems: "center", gap: 8, minHeight: 24 }}>
        <span style={{ fontSize: 12, color: ev.stato === "iscrizioni" ? C.accent500 : C.slate400, fontWeight: ev.stato === "iscrizioni" ? 700 : 400, lineHeight: 1.3, ...num }}>{ev.statoTxt}</span>
        {ev.extra && <span style={{ marginLeft: "auto", fontSize: 11, color: ev.extra.includes("Added") ? C.gold : C.slate500, fontWeight: 600, flexShrink: 0, ...num }}>{ev.extra}</span>}
      </div>
    </div>
  );
}

export default function HomePortale() {
  const [q, setQ] = useState("");
  const [regione, setRegione] = useState("Tutte");

  const filtrati = useMemo(() => EVENTI.filter((e) => {
    const okR = regione === "Tutte" || e.regione === regione;
    const okQ = !q || (e.nome + " " + e.luogo).toLowerCase().includes(q.toLowerCase());
    return okR && okQ;
  }), [q, regione]);

  const live = filtrati.find((e) => e.stato === "live");
  const prossimi = filtrati.filter((e) => ["iscrizioni", "annunciato"].includes(e.stato));
  const conclusi = filtrati.filter((e) => e.stato === "concluso");
  const vuoto = filtrati.length === 0;

  return (
    <div style={{ minHeight: "100vh", background: C.ink900, color: C.white, fontFamily: "-apple-system, 'Segoe UI', Roboto, sans-serif", display: "flex", flexDirection: "column" }}>
      {/* nav */}
      <div style={{ maxWidth: 1280, width: "100%", margin: "0 auto", boxSizing: "border-box", padding: "12px 24px", display: "flex", alignItems: "center", gap: 20 }}>
        <span style={{ display: "flex", alignItems: "center", gap: 9 }}>
          <span style={{ width: 26, height: 26, borderRadius: 7, background: C.accent, display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 14 }}>P</span>
          <strong style={{ fontSize: 16, letterSpacing: -0.3 }}>PenRunner</strong>
        </span>
        <NavLink>Calendario</NavLink>
        <NavLink>Risultati</NavLink>
        <NavLink>Cavalli &amp; cavalieri</NavLink>
        <span style={{ marginLeft: "auto", display: "flex", gap: 8 }}>
          <button style={{ background: "none", border: `1px solid ${C.panel2}`, borderRadius: 8, color: C.slate300, fontSize: 12.5, padding: "7px 14px", cursor: "pointer" }}>Accedi</button>
          <button style={{ background: C.accent, border: "none", borderRadius: 8, color: C.white, fontSize: 12.5, fontWeight: 700, padding: "8px 14px", cursor: "pointer" }}>Organizza un evento</button>
        </span>
      </div>

      {/* HERO: la diretta comanda */}
      {live && (
        <div style={{ position: "relative", overflow: "hidden", height: "min(44vw, 360px)", minHeight: 250, cursor: "pointer" }}>
          <Cover ev={live} />
          <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to top, #0B1120 2%, rgba(11,17,32,.5) 50%, rgba(11,17,32,.12) 100%)" }} />
          <div style={{ position: "absolute", left: 0, right: 0, bottom: 22 }}>
            <div style={{ maxWidth: 1280, margin: "0 auto", padding: "0 24px" }}>
              <span style={{ display: "inline-flex", alignItems: "center", gap: 7, background: "#7F1D1D", color: "#FCA5A5", borderRadius: 6, padding: "5px 11px", fontSize: 11.5, fontWeight: 800 }}>
                <span style={{ width: 8, height: 8, borderRadius: 99, background: C.live }} /> IN DIRETTA
              </span>
              <h1 style={{ fontSize: 30, margin: "8px 0 2px", letterSpacing: -0.5 }}>{live.nome}</h1>
              <div style={{ fontSize: 13.5, color: C.slate300, ...num }}>{live.statoTxt} · {live.luogo}</div>
              <button style={{ marginTop: 12, background: C.accent, color: C.white, border: "none", borderRadius: 9, padding: "11px 20px", fontSize: 14, fontWeight: 800, cursor: "pointer" }}>{live.cta}</button>
            </div>
          </div>
        </div>
      )}

      {/* corpo in gabbia */}
      <div style={{ maxWidth: 1280, width: "100%", margin: "0 auto", boxSizing: "border-box", padding: "0 24px 56px", flex: 1 }}>
        {/* barra prodotto: ricerca + filtri regione */}
        <div style={{ display: "flex", gap: 10, alignItems: "center", flexWrap: "wrap", margin: "18px 0 6px" }}>
          <div style={{ position: "relative", flex: "1 1 300px", maxWidth: 440 }}>
            <Lente />
            <input value={q} onChange={(e) => setQ(e.target.value)} placeholder="Cerca eventi, cavalli, cavalieri…"
              style={{ width: "100%", boxSizing: "border-box", background: C.panel, border: `1px solid ${C.panel2}`, borderRadius: 10, padding: "10px 14px 10px 36px", fontSize: 13, color: C.white, outline: "none" }} />
          </div>
          <div style={{ display: "flex", gap: 6, flexWrap: "wrap", marginLeft: "auto" }}>
            {REGIONI.map((r) => (
              <button key={r} onClick={() => setRegione(r)} style={{
                border: regione === r ? "none" : `1px solid ${C.panel2}`, borderRadius: 8, padding: "7px 12px",
                fontSize: 12, fontWeight: 600, cursor: "pointer",
                background: regione === r ? C.white : "transparent", color: regione === r ? C.ink900 : C.slate300,
              }}>{r}</button>
            ))}
          </div>
        </div>

        {vuoto && (
          <div style={{ padding: 48, textAlign: "center", color: C.slate500, fontSize: 13.5, background: C.panel, borderRadius: 12, marginTop: 14 }}>
            Nessun evento per questa ricerca. Prova a cambiare regione o termine.
          </div>
        )}

        {prossimi.length > 0 && (
          <>
            <h2 style={{ fontSize: 13, color: C.slate400, textTransform: "uppercase", letterSpacing: 1, margin: "20px 0 12px" }}>Prossimi eventi</h2>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(330px, 1fr))", gap: 14 }}>
              {prossimi.map((e) => <CardEvento key={e.id} ev={e} />)}
            </div>
          </>
        )}

        {conclusi.length > 0 && (
          <>
            <h2 style={{ fontSize: 13, color: C.slate400, textTransform: "uppercase", letterSpacing: 1, margin: "28px 0 12px" }}>Conclusi di recente</h2>
            <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 12 }}>
              {conclusi.map((e) => (
                <div key={e.id} style={{ borderRadius: 10, overflow: "hidden", background: C.panel, cursor: "pointer" }}>
                  <div style={{ position: "relative", aspectRatio: "16/9" }}>
                    <Cover ev={e} />
                    <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to top, rgba(11,17,32,.94) 0%, rgba(11,17,32,.30) 55%, rgba(11,17,32,0) 100%)" }} />
                    <div style={{ position: "absolute", left: 10, right: 10, bottom: 8, color: C.white }}>
                      <div style={{ fontSize: 9.5, color: C.slate300, textTransform: "uppercase", letterSpacing: 0.8, ...num }}>{e.date}</div>
                      <div style={{ fontSize: 13.5, fontWeight: 800 }}>{e.nome}</div>
                    </div>
                  </div>
                  <div style={{ padding: "7px 10px 10px" }}>
                    <div style={{ fontSize: 10.5, color: C.gold, fontWeight: 700, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis", ...num }}>{e.statoTxt}</div>
                    <div style={{ fontSize: 11, color: C.accent500, fontWeight: 600, marginTop: 2 }}>Risultati →</div>
                  </div>
                </div>
              ))}
            </div>
          </>
        )}
      </div>

      {/* footer */}
      <div style={{ borderTop: `1px solid ${C.panel2}`, padding: "22px 24px" }}>
        <div style={{ maxWidth: 1280, margin: "0 auto", display: "flex", alignItems: "center", gap: 11, flexWrap: "wrap", color: C.slate500, fontSize: 12.5 }}>
          <span style={{ width: 22, height: 22, borderRadius: 6, background: C.accent, display: "inline-flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 12, color: C.white }}>P</span>
          <strong style={{ color: C.slate300, fontSize: 13.5 }}>PenRunner</strong>
          <span>Il reining, in diretta</span>
          <span style={{ marginLeft: "auto" }}>IRHA · FISE · Italia</span>
        </div>
      </div>
    </div>
  );
}
